<script>
 import {onMount} from 'svelte';import {locale} from '$lib/i18n.js';import {goto} from '$app/navigation';import {listProjects,listWorkspaces,createProject,deleteProject} from '$lib/api.js';import {notify} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';import Modal from '$lib/components/Modal.svelte';
 let projects=[];let search='';let statusFilter='all';let deviceFilter='all';let view='list';let workspaces=[];let selectedOwner='';let loading=true;let saving=false;let showCreate=false;let name='';let description='';
 $: ru=$locale!=='en';
 $: manageableWorkspaces=workspaces.filter(w=>w.can_manage_members);
 $: filteredProjects=projects.filter(p=>{const q=search.trim().toLowerCase();if(q&&!(p.name+' '+(p.description||'')+' '+(p.slug||'')).toLowerCase().includes(q))return false;if(statusFilter==='active'&&(Number(p.device_count||0)+Number(p.site_count||0)===0))return false;if(statusFilter==='empty'&&(Number(p.device_count||0)+Number(p.site_count||0)>0))return false;if(deviceFilter==='with'&&!Number(p.device_count||0))return false;if(deviceFilter==='without'&&Number(p.device_count||0))return false;return true});
 async function load(){const [r,w]=await Promise.all([listProjects(),listWorkspaces()]);if(r.ok)projects=r.data.projects||[];else notify(r.error||'Не удалось загрузить проекты','error');if(w.ok){workspaces=w.data.workspaces||[];const allowed=workspaces.filter(x=>x.can_manage_members);if(!allowed.some(x=>String(x.owner_user_id)===String(selectedOwner)))selectedOwner=String(allowed[0]?.owner_user_id||'')}else notify(w.error||'Не удалось загрузить рабочие области','error');loading=false}
 onMount(load);
 async function create(){saving=true;const r=await createProject(name,description,selectedOwner);saving=false;if(!r.ok){notify(r.error||'Не удалось создать проект','error');return}notify('Проект создан','success');showCreate=false;name='';description='';await load()}
 async function remove(p){if(!confirm('Удалить проект? Устройства, сайты и их данные останутся без изменений.'))return;const r=await deleteProject(p.id);if(r.ok){notify('Проект удалён','success');await load()}else notify(r.error||'Ошибка удаления','error')}
</script>
<svelte:head><title>Projects · VELTRIX Dock</title></svelte:head>
<div class="page-header"><div><div class="eyebrow">WORKSPACE</div><h1 class="page-title">{ru?'Проекты':'Projects'}</h1><p class="page-desc">{ru?'Все приложения и сервисы в одном месте.':'All your applications and services in one place.'}</p></div>{#if manageableWorkspaces.length}<Button variant="primary" on:click={()=>showCreate=true}>＋ {ru?'Новый проект':'New project'}</Button>{/if}</div>
{#if loading}<div class="empty">Загрузка проектов…</div>{:else if !projects.length}<div class="empty"><strong>{ru?'Пока нет проектов':'No projects yet'}</strong><p>{ru?'Создай проект и добавь в него устройства и приложения.':'Create a project and add devices and applications.'}</p>{#if manageableWorkspaces.length}<Button variant="primary" on:click={()=>showCreate=true}>{ru?'Создать проект':'Create project'}</Button>{/if}</div>{:else}
<div class="project-toolbar"><input class="input" bind:value={search} placeholder={ru?'Поиск проектов…':'Search projects…'}/><select class="input" bind:value={statusFilter}><option value="all">{ru?'Все статусы':'All statuses'}</option><option value="active">{ru?'С ресурсами':'Has resources'}</option><option value="empty">{ru?'Пустые':'Empty'}</option></select><select class="input" bind:value={deviceFilter}><option value="all">{ru?'Все устройства':'All devices'}</option><option value="with">{ru?'Есть устройства':'Has devices'}</option><option value="without">{ru?'Без устройств':'No devices'}</option></select><div class="view-switch"><button class:active={view==='list'} on:click={()=>view='list'} aria-label="List view">☰</button><button class:active={view==='grid'} on:click={()=>view='grid'} aria-label="Grid view">▦</button></div></div>
{#if !filteredProjects.length}<div class="empty">{ru?'Проекты по заданным фильтрам не найдены.':'No projects match these filters.'}</div>{:else}<div class:project-grid={view==='grid'} class="project-list">{#each filteredProjects as p}<article class="project-row"><button class="project-main" on:click={()=>goto('/projects/'+p.id)}><span class="project-icon">▦</span><span class="project-copy"><strong>{p.name}</strong><small>{p.description||p.slug}</small></span><span class="project-stats">{p.device_count||0} {ru?'устройств':'devices'} · {p.site_count||0} {ru?'приложений':'apps'}</span><span class="arrow">→</span></button>{#if p.can_manage}<Button variant="ghost" size="sm" on:click={()=>remove(p)}>{ru?'Удалить':'Delete'}</Button>{/if}</article>{/each}</div>{/if}{/if}
<Modal open={showCreate} title={ru?'Создать проект':'Create project'} onClose={()=>showCreate=false}><div class="field"><label for="project-workspace">{ru?'Рабочая область':'Workspace'}</label><select id="project-workspace" class="input" bind:value={selectedOwner}>{#each manageableWorkspaces as w}<option value={String(w.owner_user_id)}>{w.owner_username} · {w.role}</option>{/each}</select></div><div class="field"><label for="project-name">{ru?'Название':'Project name'}</label><input id="project-name" class="input" bind:value={name} maxlength="80" placeholder="Например, Personal websites"/></div><div class="field"><label for="project-desc">{ru?'Описание':'Description'}</label><textarea id="project-desc" class="input" bind:value={description} rows="3" maxlength="500" placeholder="Краткое описание проекта"/></div><div class="source-note"><span>{ru?'Источник кода':'Source repository'}</span><a href="/settings/integrations/github">GitHub App ↗</a><small>{ru?'Импорт репозитория в проект появится после реализации project-source lifecycle.':'Repository import will be enabled when project-source lifecycle is implemented.'}</small></div><svelte:fragment slot="footer"><Button on:click={()=>showCreate=false}>{ru?'Отмена':'Cancel'}</Button><Button variant="primary" loading={saving} disabled={name.trim().length<2} on:click={create}>{ru?'Создать':'Create project'}</Button></svelte:fragment></Modal>
<style>
.project-toolbar{display:flex;gap:8px;margin-bottom:12px}.project-toolbar input{flex:1;min-width:140px}.project-toolbar select{width:auto;min-width:125px}.view-switch{display:flex;gap:3px;padding:3px;border:1px solid var(--border);border-radius:7px}.view-switch button{padding:4px 8px;border:0;border-radius:4px;background:transparent;color:var(--text-muted)}.view-switch button.active{background:var(--bg-elevated);color:var(--accent)}.project-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr))}.project-grid .project-row{align-items:flex-start;flex-direction:column}.project-grid .project-main{width:100%;flex-wrap:wrap}.source-note{display:grid;gap:4px;padding:10px;border:1px solid var(--border);border-radius:7px;font-size:10px}.source-note a{color:var(--accent)}.source-note small{color:var(--text-muted);font-size:9px}.eyebrow{font-size:9px;letter-spacing:.14em;color:#818cf8;font-weight:700;margin-bottom:7px}.project-list{border:1px solid #253149;border-radius:12px;background:#101727;overflow:hidden}.project-row{display:flex;align-items:center;gap:10px;padding:10px 13px;border-bottom:1px solid #1e293b}.project-row:last-child{border:0}.project-main{display:flex;align-items:center;gap:11px;flex:1;min-width:0;text-align:left;border:0;background:none;color:#f1f5f9}.project-icon{width:32px;height:32px;border-radius:8px;background:#242b50;color:#a5b4fc;display:grid;place-items:center}.project-copy{display:grid;gap:3px;min-width:0;flex:1}.project-copy strong{font-size:11px}.project-copy small,.project-stats{font-size:9px;color:#64748b;overflow:hidden;text-overflow:ellipsis}.arrow{color:#64748b}.field{display:grid;gap:6px;margin:12px 0}.field label{font-size:10px;color:#94a3b8}.field textarea{resize:vertical}
@media(max-width:700px){.project-toolbar{flex-wrap:wrap}.project-toolbar input{flex-basis:100%}.project-toolbar select{flex:1;min-width:0}.view-switch{margin-left:auto}}@media(max-width:600px){.project-stats{display:none}.project-row{padding:9px}}
</style>